const IMBUE_BY_ID = new Map(IMBUEMENTS.map((x) => [x.id, x]));
export const getImbuement = (id: string): ImbueDef | undefined => IMBUE_BY_ID.get(id);
export const IMBUE_LEVELS = [1, 2, 3] as const;
export type ImbueLevel = (typeof IMBUE_LEVELS)[number];

/**
 * Imbuements for a slot; skill imbuements only for the vocation's skills (also when the item already raises the skill,
 * D85). An item with a native element protection, critical hit, life or mana leech cannot take the imbuement of the
 * same kind (D83).
 */
export function imbuementsFor(slot: ImbueSlot, vocation: Vocation, item?: EquipmentItem): ImbueDef[] {
  const skills = VOCATION_SKILLS[vocation];
  const own = item?.bonus;
  return IMBUEMENTS.filter(
    (x) =>
      x.slots.includes(slot) &&
      (!x.skill || skills.includes(x.skill)) &&
      !(x.group === 'damage' && MAGE.has(vocation)) &&
      !(x.group === 'protection' && x.element && own?.resist?.[x.element as keyof typeof own.resist]) &&
      !nativeOf(x, own),
  ).map((x) => (x.skill === 'magic' && slot === 'helmet' && !mageHelmet(item) ? { ...x, levels: NON_MAGE_EPIPHANY } : x));
}

/** D96: on helmets that are not mage-exclusive Epiphany is Intricate only (Basic / Powerful: mage helmets; TibiaWiki). */
const NON_MAGE_EPIPHANY = [2] as const;
const mageHelmet = (item: EquipmentItem | undefined) => !!item?.vocations?.length && item.vocations.every((v) => MAGE.has(v));

/** D96: the level kept for an imbuement (the highest allowed one when `level` is not available). */
export const imbueLevelFor = (x: Pick<ImbueDef, 'levels'>, level: 1 | 2 | 3): 1 | 2 | 3 =>
  !x.levels || x.levels.includes(level) ? level : x.levels[x.levels.length - 1];

/** D83: a native critical hit, life or mana leech blocks Strike, Vampirism or Void. */
const nativeOf = (x: ImbueDef, own: { critChance?: number; lifeLeech?: number; manaLeech?: number } | undefined) =>
  (x.group === 'crit' && !!own?.critChance) || (x.group === 'lifeLeech' && !!own?.lifeLeech) || (x.group === 'manaLeech' && !!own?.manaLeech);

const MAGE = new Set<Vocation>(['sorcerer', 'druid']);
const VOCATION_SKILLS: Record<Vocation, readonly ItemSkill[]> = {
  knight: ['sword', 'axe', 'club', 'magic', 'shielding'],
  paladin: ['distance', 'magic', 'shielding'],
  sorcerer: ['magic', 'shielding'],
  druid: ['magic', 'shielding'],
  monk: ['fist', 'magic', 'shielding'],
};

/** D84: weapon types a skill imbuement fits (TibiaWiki: Punch on fist weapons, Precision on bows and crossbows, …). */
const SKILL_WEAPONS: Partial<Record<ItemSkill, readonly string[]>> = {
  fist: ['fist'],
  club: ['club'],
  sword: ['sword'],
  axe: ['axe'],
  distance: ['bow', 'crossbow'],
  magic: ['wand', 'rod'],
};
const ELEMENT_DAMAGE_WEAPONS = new Set(['fist', 'club', 'sword', 'axe', 'bow', 'crossbow']);
/**
 * D48 / D87: Inferniarch variants that cannot take an imbuement: Rending no Strike, Siphoning no Void, Draining no
 * Vampirism (TibiaWiki; shared by the editor and the engine).
 */
export const noCritImbue = (w: { id: string }) => w.id.startsWith('rending-inferniarch-');
export const noLifeLeechImbue = (w: { id: string }) => w.id.startsWith('draining-inferniarch-');
export const noManaLeechImbue = (w: { id: string }) => w.id.startsWith('siphoning-inferniarch-');

/** D84: wands and rods below this level cannot take Strike. */
const STRIKE_MIN_WAND_LEVEL = 150;

/**
 * D81 / D84: imbuements a weapon can take. Skill imbuements only of its own skill (also when the weapon already raises
 * it); elemental damage only on melee weapons, bows and crossbows that do not deal elemental damage themselves (a
 * monk's elemental bond does not count); no Strike on wands / rods below level 150; a native critical hit, life or
 * mana leech blocks Strike, Vampirism or Void (D83); Inferniarch variants (D86).
 */
export function weaponImbuements(
  w: { id?: string; type?: string; minLevel?: number; element?: string; elementAttack?: unknown; specials?: { critChance?: number; lifeLeech?: number; manaLeech?: number } },
  vocation: Vocation,
): ImbueDef[] {
  const type = w.type ?? '';
  const elemental = !!w.elementAttack || (!!w.element && w.element !== 'physical' && type !== 'fist');
  const wand = type === 'wand' || type === 'rod';
  return imbuementsFor('weapon', vocation).filter(
    (x) =>
      !(x.skill && !SKILL_WEAPONS[x.skill]?.includes(type)) &&
      !(x.group === 'damage' && (elemental || !ELEMENT_DAMAGE_WEAPONS.has(type))) &&
      !(x.group === 'crit' && wand && (w.minLevel ?? 0) < STRIKE_MIN_WAND_LEVEL) &&
      !nativeOf(x, w.specials) &&
      !(w.id && ((x.group === 'crit' && noCritImbue({ id: w.id })) || (x.group === 'lifeLeech' && noLifeLeechImbue({ id: w.id })) || (x.group === 'manaLeech' && noManaLeechImbue({ id: w.id })))),
  );
}

/** Imbuement slots of a weapon (unknown weapon: the usual maximum). */
export const WEAPON_IMBUE_SLOTS = 3;

// ---------------------------------------------------------------------------
// Exaltation Forge tiers (chance %, tiers 1..10; tiers 7–10 extrapolated from the second differences)

export type TierEffect = 'onslaught' | 'ruse' | 'momentum' | 'transcendence' | 'amplification';

export const TIER_EFFECT: Partial<Record<GearSlot | 'weapon', TierEffect>> = {
  weapon: 'onslaught',
  armor: 'ruse',
  helmet: 'momentum',
  legs: 'transcendence',
  boots: 'amplification',
};

export const TIER_CHANCE: Record<TierEffect, readonly number[]> = {
  onslaught: [0.5, 1.05, 1.7, 2.45, 3.3, 4.25, 5.3, 6.45, 7.7, 9.05],
  ruse: [0.5, 1.03, 1.62, 2.28, 3.0, 3.78, 4.62, 5.53, 6.5, 7.53],
  momentum: [2.0, 4.05, 6.2, 8.45, 10.8, 13.25, 15.8, 18.45, 21.2, 24.05],
  transcendence: [0.13, 0.27, 0.44, 0.64, 0.86, 1.11, 1.39, 1.7, 2.04, 2.41],
  amplification: [2.5, 5.4, 9.1, 13.6, 18.9, 25.0, 31.9, 39.6, 48.1, 57.4],
};

export const MAX_TIER = 10;

/** Highest tier of an item class (class 4: 10; lower classes: their number; no class: 0). */
export const maxTier = (cls: number | undefined): number => (!cls ? 0 : cls >= 4 ? MAX_TIER : cls);

export const tierChance = (effect: TierEffect, tier: number): number => (tier >= 1 ? TIER_CHANCE[effect][Math.min(MAX_TIER, tier) - 1] : 0);
